() => {
 if (location.hostname !== 'play.google.com' || !location.pathname.startsWith('/store/search')) throw new Error('Google Play 搜索被重定向，请查看当前页面');
 const items = new Map();
 for (const a of document.querySelectorAll('a[href*="/store/apps/details?id="]')) {
  const url = new URL(a.href); const id = url.searchParams.get('id');
  const lines = a.innerText.split('\n').map(s => s.trim()).filter(Boolean);
  const name = a.getAttribute('aria-label') || lines[0];
  if (!id || !name || items.has(id)) continue;
  items.set(id, {id, name, listingText: lines.join(' · '), ratingLabel: a.querySelector('[role="img"][aria-label]')?.getAttribute('aria-label') || null, url: url.href});
 }
 if (!items.size) throw new Error('未找到应用结果：可能无匹配、页面验证或页面结构发生变化，请查看页面确认');
 return [...items.values()].slice(0,20);
}
